class Solution {
public:
    int findTargetSumWays(vector<int>& nums, int target) {
        int total = 0;
        for (int x : nums) total += x;
        if ((target + total) % 2 != 0) return 0;
        int S = (target + total) / 2;
        if (S < 0) return 0;
        vector<int> dp(S + 1, 0);
        dp[0] = 1;
        for (int x : nums) {
            for (int j = S; j >= x; --j) {
                dp[j] += dp[j - x];
            }
        }
        return dp[S];
    }
};
